mapper.select:
select
orderInfo.*
from order_info orderInfo
left join proprietor proprietor on orderInfo.user_id = proprietor.id

    and orderInfo.id = #{id}
    and orderInfo.user_id = #{userId}
    and orderInfo.car_number like concat('%',#{carNumber},'%')
    and orderInfo.in_time = #{inTime}
    and orderInfo.out_time = #{outTime}
    and orderInfo.money = #{money}
    and orderInfo.status = #{status}
    and orderInfo.hour = #{hour}
    and orderInfo.create_time = #{createTime}

order by id desc

    limit #{current},#{pageSize}

select count(*) from order_info orderInfo
left join proprietor proprietor on orderInfo.user_id = proprietor.id

    and orderInfo.id = #{id}
    and orderInfo.user_id = #{userId}
    and orderInfo.car_number like concat('%',#{carNumber},'%')
    and orderInfo.in_time = #{inTime}
    and orderInfo.out_time = #{outTime}
    and orderInfo.money = #{money}
    and orderInfo.status = #{status}
    and orderInfo.hour = #{hour}
    and orderInfo.create_time = #{createTime}
